[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = one;
	alpha = -r[noarr::idx<'i'>(0)];

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		// iterate original k-indices in [1, n-1]
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta = (one - alpha * alpha) * beta;

			// sum = 0.0;
			sum = zero;

			// sum = sum_{i=0}^{k-1} r[k - i - 1] * y[i];
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k)) // i in [0, k-1]
				.for_each([&](auto iy_state) {
					auto i = noarr::get_index<'i'>(iy_state);
					auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[iy_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// In-place update of y[0..k-1].
			//
			// Original code:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// We avoid the temporary z[ ] as follows:
			//   * For each pair (i, j = k-i-1) with i < j, compute
			//       new_y[i] = y[i] + alpha * y[j];
			//       new_y[j] = y[j] + alpha * y[i];
			//     using the original values y[i], y[j] stored in temporaries
			//     and then write both back to y[ ].
			//   * When i == j (only possible if k is odd), we have
			//       new_y[i] = y[i] + alpha * y[i] = (1+alpha)*y[i],
			//     which is identical to the original expression with z.
			//   * When i > j, the (j, i) pair has already been processed
			//     earlier (at index j < i), so we skip.
			//
