			// from three passes over y (sum, z-write, copy-back) down to two
			// (sum, in-place update).
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k)) // i in [0, k-1]
				.for_each([&](auto i_state) {
					auto i = noarr::get_index<'i'>(i_state);
					auto j = k - i - 1;

					if (i < j) {
						auto j_state = noarr::idx<'i'>(j);

						num_t yi = y[i_state];
						num_t yj = y[j_state];

						y[i_state] = yi + alpha * yj;
						y[j_state] = yj + alpha * yi;
					} else if (i == j) {
						// Center element when k is odd.
						num_t yi = y[i_state];
						y[i_state] = yi + alpha * yi;
					} else {
						// i > j: the (j, i) pair was already processed.
					}
				});

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

