//
// Optimizations compared to the original version:
//  - Remove the temporary vector z and update y[] in-place using pairwise
//    updates (i, k-i-1). This keeps the semantics identical while halving
//    the number of passes over y[] for each k.
//  - Fuse the "z = ..." and "y = z" loops into a single loop.
//  - Simplify the k-loop by using for_each on a 1D 'k' structure instead of
//    for_dims<'k'> with an inner traverser.
//  - In the sum loop, walk r[] backwards using a state that is decremented
//    each iteration instead of recomputing k-i-1 each time.
//  - Keep all loop nests expressed via Noarr traversers, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);

#pragma scop
