	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = one;
	alpha = -r[noarr::idx<'i'>(0)];

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.for_each([&](auto k_state) {
			auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta *= (one - alpha * alpha);

			// sum = 0.0;
			sum = zero;

			// Compute sum = sum_{i=0}^{k-1} r[k - i - 1] * y[i]
			// We walk y[i] with a traverser and r[j] with a separate
			// state j that starts at k-1 and is decremented each step.
			auto r_state_rev = noarr::idx<'i'>(k - 1);

			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto yi_state) {
					sum += r[r_state_rev] * y[yi_state];
					// move r_state_rev to the previous element
					r_state_rev = r_state_rev - noarr::idx<'i'>(1);
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// In-place update of y[0..k-1] without a temporary z[]:
			//   old_y_i = y[i]
			//   old_y_j = y[k-i-1]
			//   new_y_i = old_y_i + alpha * old_y_j
			//   new_y_j = old_y_j + alpha * old_y_i
