					num_t yj = y[j_state];

					num_t yi_new = yi + alpha * yj;
					num_t yj_new = yj + alpha * yi;

					y[yi_state] = yi_new;
					y[j_state]  = yj_new;

					// Move j one position towards the beginning for the next pair
					j_state = j_state - noarr::idx<'i'>(1);
				});

			// If k is odd, there is a single middle element that does not
			// form a pair. For that index m = half we need:
			//   y[m] = y[m] + alpha * y[m] = (1 + alpha) * y[m]
