				auto mid_state = noarr::idx<'i'>(half);
				num_t ym = y[mid_state];
				y[mid_state] = ym + alpha * ym;
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
