// computation kernel
//
// Optimization compared to the straightforward PolyBench-like version:
//   The reference algorithm uses three sweeps over y[0..k-1] for each k:
//     1) compute sum
//     2) compute z[i] = y[i] + alpha * y[k-i-1]
//     3) copy z back to y
//
//   We reduce this to two sweeps per k without changing the numerical
//   result:
//
//     - In the first sweep we compute `sum` and simultaneously store the
//       mirrored values y[k-i-1] into a temporary buffer `y_mirror[i]`.
//       This buffer holds the *old* values of y[k-i-1] for all i.
//
//     - After alpha is known, the second sweep performs the in‑place
//       update
//           y[i] = y[i] + alpha * y_mirror[i]
//       which is algebraically equivalent to the original
//           z[i] = y[i] + alpha * y[k-i-1];
//           y[i] = z[i];
//
//   The temporary buffer has the same size as the original z[], so the
//   memory footprint is unchanged, but we cut one full pass over the data
//   for every k, improving data locality and reducing memory traffic.
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// local temporary y_mirror[0..n-1], used to store mirrored y[k-i-1]
	auto y_mirror = noarr::bag(noarr::scalar<num_t>() ^ noarr::vector<'i'>(n));

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = SCALAR_VAL(1.0);
	alpha = -r[noarr::idx<'i'>(0)];

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			// current k index
			auto k_state = k_trav.state();
			auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// First sweep over i = 0..k-1:
			//   - accumulate sum += r[k-i-1] * y[i]
			//   - cache y[k-i-1] into y_mirror[i]
			noarr::traverser(y, r, y_mirror)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto state) {
					auto i = noarr::get_index<'i'>(state);

					// reversed index k-i-1 in dimension 'i'
					auto rev_state = noarr::idx<'i'>(k - i - 1);

					// contribution to the Durbin sum
					sum += r[rev_state] * y[state];

					// store old y[k-i-1] so that we can update y in-place later
					y_mirror[state] = y[rev_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// Second sweep over i = 0..k-1:
			//   y[i] = y[i] + alpha * y_mirror[i];
			// This is equivalent to:
			//   z[i] = y[i] + alpha * y[k-i-1];
			//   y[i] = z[i];
			// but uses y_mirror instead of an extra z[] + copy.
			noarr::traverser(y, y_mirror)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto state) {
					y[state] = y[state] + alpha * y_mirror[state];
				});

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n);

