// computation kernel
//
// Optimizations applied:
//
// 1. Removed the temporary vector z[0..n-1] and two separate loops
//    (computing z[i] and then copying z[i] back to y[i]).
//    The transformation exploits symmetry:
//        z[i]   = y[i] + alpha * y[k-1-i]
//        y[i]   = z[i]
//    for i = 0..k-1 can be performed in-place by processing index
//    pairs (i, j = k-1-i) together:
//
//        yi = y[i]; yj = y[j];
//        y[i] = yi + alpha * yj;
//        y[j] = yj + alpha * yi;
//
//    This uses only original y values (stored into yi,yj first) and
//    exactly reproduces the effect of the original algorithm while
//    halving the number of updates and eliminating the temporary array.
//
//    The loop runs only for i in [0, (k+1)/2), so each pair {i, j} is
//    processed exactly once.
//
// 2. The inner “sum” loop traverses only y using a traverser over 'i'.
//    r is accessed via explicit index states. This reduces the amount of
//    multi-structure traversal bookkeeping while preserving semantics.
//
// 3. Constants SCALAR_VAL(1.0) and SCALAR_VAL(0.0) are hoisted to local
//    const variables to avoid repeated macro expansion and conversions.
//
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);

	#pragma scop
	// y[0] = -r[0];
	const auto i0_state = noarr::idx<'i'>(0);
	const num_t r0 = r[i0_state];
	y[i0_state] = -r0;
	beta = one;
	alpha = -r0;

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			// current k index
			auto k_state = k_trav.state();
			const auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta = (one - alpha * alpha) * beta;

			// sum = 0.0;
			sum = zero;

			// sum = sum_{i=0}^{k-1} r[k - i - 1] * y[i];
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto y_state) {
					const auto i = noarr::get_index<'i'>(y_state);
					auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[y_state];
				});

			// alpha = - (r[k] + sum) / beta;
			const auto rk_state = noarr::idx<'i'>(k);
			alpha = -(r[rk_state] + sum) / beta;

			// Original code:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// Optimized in-place symmetric update:
			//   process pairs (i, j = k-1-i); each pair uses only original
			//   y[i], y[j] values captured into temporaries yi,yj.
			//
			// Effective range of distinct pairs and center element:
			//   i in [0, (k+1)/2)
			const auto half_len = (k + 1) / 2;

			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, half_len))
				.for_each([&](auto yi_state) {
					const auto i = noarr::get_index<'i'>(yi_state);
					const auto j = k - 1 - i;

					auto yj_state = noarr::idx<'i'>(j);

					// Read original values before any write
					const num_t yi = y[yi_state];
					const num_t yj = y[yj_state];

					const num_t new_yi = yi + alpha * yj;
					const num_t new_yj = yj + alpha * yi;

					// Safe even when i == j: both assignments write
					// the same value to the same element.
					y[yi_state] = new_yi;
					y[yj_state] = new_yj;
				});

			// y[k] = alpha;
			y[rk_state] = alpha;
		});
	#pragma endscop
