#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "durbin.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();

struct tuning {
	// 1D layout over dimension 'i'
	DEFINE_PROTO_STRUCT(r_layout, i_vec);
	DEFINE_PROTO_STRUCT(y_layout, i_vec);
} tuning;

// initialization function: r[i] = n + 1 - i
void init_array(auto r) {
	using namespace noarr;

	auto n = r | get_length<'i'>();

	traverser(r).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		r[state] = (num_t)(n + 1 - i);
	});
}

// computation kernel
//
// Optimizations vs original:
// - Eliminate the temporary array z[0..n-1] and update y[0..k-1] in-place.
//   This removes two full passes over y per outer iteration and one extra
//   dynamically allocated vector, improving memory bandwidth and locality.
// - Simplify traverser usage (no unnecessary multi-structure traversers,
//   simpler k-loop traversal).
// - Keep all loops expressed via noarr::traverser as required.
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop (k in [0, n-1])
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// y[0] = -r[0];
	const auto i0 = noarr::idx<'i'>(0);
	y[i0] = -r[i0];

	beta = SCALAR_VAL(1.0);
	alpha = -r[i0];

	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1)) // iterate k in [1, n-1]
		.for_each([&](auto k_state) {
			const auto k = noarr::get_index<'k'>(k_state);

			// beta = (1 - alpha * alpha) * beta;
			beta *= (SCALAR_VAL(1.0) - alpha * alpha);

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// sum = sum_{i=0..k-1} r[k - i - 1] * y[i];
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k)) // i in [0, k-1]
				.for_each([&](auto i_state) {
					const auto i = noarr::get_index<'i'>(i_state);
					const auto r_state = noarr::idx<'i'>(k - i - 1);
					sum += r[r_state] * y[i_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// In-place update of y[0..k-1] without using an auxiliary z array.
			//
			// Original code:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// This defines:
			//   y_new[i] = y_old[i] + alpha * y_old[k - 1 - i]
			//
			// We exploit the pairing (i, j = k-1-i). For i < j:
			//   y_new[i] = y_old[i] + alpha * y_old[j]
			//   y_new[j] = y_old[j] + alpha * y_old[i]
			// and for the center element when k is odd (i == j):
			//   y_new[i] = y_old[i] + alpha * y_old[i]
			//
			// We iterate i in [0, ceil(k/2)-1] and update pairs (i, j)
			// in-place using saved old values, so each index 0..k-1 is
			// written exactly once and only depends on y_old.
			const std::size_t k_minus_1 = k - 1;
			const std::size_t half_len  = (k + 1) / 2; // ceil(k/2)

			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, half_len))
				.for_each([&](auto i_state) {
					const auto i = noarr::get_index<'i'>(i_state);
					const auto j = k_minus_1 - i;

					// old y[i]
					const num_t yi = y[i_state];

					if (i == j) {
						// center element for odd k
						y[i_state] = yi + alpha * yi;
					} else {
						// paired elements (i, j), i < j
						const auto j_state = noarr::idx<'i'>(j);
						const num_t yj = y[j_state];

						// compute both new values from old yi, yj
						const num_t new_yi = yi + alpha * yj;
						const num_t new_yj = yj + alpha * yi;

						y[i_state]  = new_yi;
						y[j_state]  = new_yj;
					}
				});

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
}

